12	func timeChain(t *testing.T, times ...*int64) *Index {
13		t.Helper()
14		index := New()
15		for i, when := range times {
16			height := int64(i + 1)
17			parent := "genesis"
18			if height > 1 {
19				parent = fmt.Sprintf("h%d", height-1)
20			}
21			block := Block{
22				Height: height,
23				Hash:   fmt.Sprintf("h%d", height),
24				Parent: parent,
25				Txs:    []string{"a"},
26				Time:   when,
27			}
28			if err := index.Append(block); err != nil {
29				t.Fatalf("setup append at %d: %v", height, err)
30			}
31		}
32		return index
33	}
34	
35	func TestQueryTxsCursorDiesOnInRangeTimestampChange(t *testing.T) {
36		t.Run("reorg changes timestamp in range", func(t *testing.T) {
37			idx := timeChain(t, intptr(10), intptr(20), intptr(30))
38			first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
39			if _, err := idx.Reorg([]Block{
40				{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(999)},
41				{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
42			}); err != nil {
43				t.Fatal(err)
44			}
45			if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
46				t.Fatalf("err=%v, want ErrQueryChanged", err)
47			}
48		})
49	
50		t.Run("missing becomes known in range", func(t *testing.T) {
51			idx := timeChain(t, intptr(10), nil, intptr(30))
52			first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
53			if _, err := idx.Reorg([]Block{
54				{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(20)},
55			}); err != nil {
56				t.Fatal(err)
57			}
58			if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
59				t.Fatalf("err=%v, want ErrQueryChanged", err)
60			}
61		})
62	
63		t.Run("restore changes timestamp in range", func(t *testing.T) {
64			idx := timeChain(t, intptr(10), intptr(20), intptr(30))
65			first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
66			snap := `{"version":2,"tip":3,"blocks":[` +
67				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"],"timestamp":10},` +
68				`{"height":2,"hash":"h2","parent":"h1","txs":["a"],"timestamp":21},` +
69				`{"height":3,"hash":"h3","parent":"h2","txs":["a"],"timestamp":30}` +
70				`]}`
71			if err := idx.Restore(strings.NewReader(snap)); err != nil {
72				t.Fatal(err)
73			}
74			if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
75				t.Fatalf("err=%v, want ErrQueryChanged", err)
76			}
77		})
78	}
79	
80	func TestQueryTxsCursorSurvivesTimestampChangeOutsideRange(t *testing.T) {
81		index := timeChain(t, intptr(10), intptr(20), intptr(30), intptr(40))
82		// Pin the query to heights 1..2.
83		first, err := index.QueryTxs(TxQuery{From: 1, To: 2, PageSize: 1})
84		if err != nil {
85			t.Fatal(err)
86		}
87		// Change only the timestamp of height 4, outside the pinned range.
88		if _, err := index.Reorg([]Block{
89			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
90			{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"a"}, Time: intptr(400)},
91		}); err != nil {
92			t.Fatal(err)
93		}
94		page, err := index.QueryTxs(TxQuery{From: 1, To: 2, PageSize: 1, Cursor: first.NextCursor})
95		if err != nil {
96			t.Fatalf("out-of-range time change killed the cursor: %v", err)
97		}
98		if page.TotalMatches != 2 || page.ToHeight != 2 {
99			t.Fatalf("unexpected page: %+v", page)
100		}
101	}
102	
103	func TestQueryTxsCursorSurvivesIdenticalTimestamps(t *testing.T) {
104		index := timeChain(t, intptr(10), intptr(20), intptr(30))
105		first, err := index.QueryTxs(TxQuery{PageSize: 1})
106		if err != nil {
107			t.Fatal(err)
108		}
109		// Reorg that replays the branch with identical hashes, txs, and times.
110		if _, err := index.Reorg([]Block{
111			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(20)},
112			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
113		}); err != nil {
114			t.Fatal(err)
115		}
116		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: first.NextCursor})
117		var hits int
118		for _, page := range pages {
119			if page.TotalMatches != 3 || page.ToHeight != 3 {
120				t.Fatalf("stats changed after identical-time replay: %+v", page)
121			}
122			hits += len(page.Hits)
123		}
124		if hits != 2 { // the first page already consumed height 1
125			t.Fatalf("continuation yielded %d hits, want 2", hits)
126		}
127	}
