1	package indexroom
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// digest constants computed independently from the pre-refactor hashTxSet
9	// algorithm; pinning them guarantees the v1 cursor set field stays
10	// byte-compatible and old cursors continue to validate.
11	func TestTxFilterDigestMatchesLegacyCursorEncoding(t *testing.T) {
12		cases := []struct {
13			name  string
14			txIDs []string
15			want  string
16		}{
17			{"unrestricted", nil, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
18			{"empty slice", []string{}, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
19			{"empty identifier only", []string{""}, "af5570f5a1810b7af78caf4bc70a660f0df51e42baf91d4de5b2328de0e83dfc"},
20			{"a and b", []string{"a", "b", "a"}, "3c9d591045bc8876f9d0399bbfb05c6a412096e906f73278f98406cd5dca86df"},
21			{"ab and c", []string{"ab", "c"}, "601d5476e2ccfe2c87a2bba7a322659734a05749d5b5aa781f513e4912db0d5f"},
22			{"a and bc", []string{"a", "bc"}, "3fafa1cf2f19a7c1129beb20cf0983f73a489a221fc0dd2f16d1be292d089205"},
23		}
24		for _, tc := range cases {
25			t.Run(tc.name, func(t *testing.T) {
26				if got := newTxFilter(tc.txIDs).hexDigest(); got != tc.want {
27					t.Fatalf("digest=%s, want legacy %s", got, tc.want)
28				}
29			})
30		}
31	}
32	
33	// TestTxFilterSetEquivalence pins the shared semantics used by both query
34	// paths and by cursor validation: order and repetitions are irrelevant, but
35	// exact string boundaries, case, and surrounding whitespace matter, and the
36	// unrestricted filter is not the same as {""}.
37	func TestTxFilterSetEquivalence(t *testing.T) {
38		groups := [][][]string{
39			{{"a", "b", "a"}, {"b", "a"}, {"b", "a", "b", "a"}},
40			{nil, {}, []string{}},
41			{{""}, {"", ""}},
42			{{"ab", "c"}, {"c", "ab", "c"}},
43			{{"a", "bc"}},
44			{{"A"}},   // case is significant: distinct from group 0's "a"
45			{{" a "}}, // surrounding whitespace is significant
46		}
47		digests := make([]string, len(groups))
48		for i, spellings := range groups {
49			want := newTxFilter(spellings[0]).hexDigest()
50			digests[i] = want
51			for _, spelling := range spellings[1:] {
52				if got := newTxFilter(spelling).hexDigest(); got != want {
53					t.Fatalf("spellings %q and %q differ: %s vs %s", spelling, spellings[0], got, want)
54				}
55			}
56		}
57		for i := 0; i < len(groups); i++ {
58			for j := i + 1; j < len(groups); j++ {
59				if digests[i] == digests[j] {
60					t.Fatalf("distinct filters collide: %q and %q -> %s", groups[i][0], groups[j][0], digests[i])
61				}
62			}
63		}
64	}
65	
66	// TestTxFilterMatching pins exact membership and the three filter modes.
67	func TestTxFilterMatching(t *testing.T) {
68		unrestricted := newTxFilter(nil)
69		for _, id := range []string{"", "a", "ab", " A ", "z"} {
70			if !unrestricted.matches(id) {
71				t.Fatalf("unrestricted filter rejected %q", id)
72			}
73		}
74	
75		onlyEmpty := newTxFilter([]string{"", ""})
76		if !onlyEmpty.matches("") {
