1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"strings"
7		"sync"
8		"testing"
9	)
10	
11	// This file guards QueryTimeStats against a main-chain reorg that makes the
12	// chain shorter. A query that is in flight when the reorg commits may answer
13	// from either the old or the new chain, but every part of ONE returned
14	// TimeStats — per-bucket counts, whole-window totals, the resolved height
15	// range, and the missing-time-block count — must come from that same complete
16	// chain. After the reorg has returned, every query must reflect the new chain
17	// only: transactions at removed heights disappear and the upper height moves
18	// with the shortened tip.
19	//
20	// The scenario (window [0,30), step 10 -> [0,10) [10,20) [20,30); height
21	// lower bound fixed at 1, upper bound left at zero so it pins the observed
22	// chain tip):
23	//
24	//	Retained ancestor (both chains):
25	//	  h1 t=0  txs [a, a]    // same id twice in one block/segment
26	//	  h2 t=5  txs [b]
27	//	Old branch, tip 5:
28	//	  h3 t=15 txs [a, c]    // a crosses segments (also in h1)
29	//	  h4 t=-  txs [d, d, e] // missing timestamp: enters no segment, and even
30	//	                        // a block with several matching txs is never counted
31	//	  h5 t=25 txs [f]       // only filler of [20,30) on the old chain
32	//	New shorter branch, tip 4 (replaces h3..h5, rooted at the retained h2):
33	//	  j3 t=10 txs [p, p, q] // different ids and multiplicities from h3
34	//	  j4 t=0  txs [r]       // zero timestamp: a real time, lands in [0,10);
35	//	                        // different time distribution, h5 simply vanishes
36	//
37	// Old-chain result (range 1..5, one missing-time block):
38	//
39	//	[0,10):  occ 3 (a,a,b), distinct {a,b}=2, blocks 2
40	//	[10,20): occ 3? no — [a,c] -> occ 2, distinct {a,c}=2, blocks 1
41	//	[20,30): occ 1 (f),      distinct {f}=1,  blocks 1
42	//	totals: occ 6, window-distinct {a,b,c,f}=4, blocks 4, missing 1
43	//
44	// New-chain result (range 1..4, no missing-time block, [20,30) returned zero):
45	//
46	//	[0,10):  occ 4 (a,a,b,r), distinct {a,b,r}=3, blocks 3
47	//	[10,20): occ 3 (p,p,q),     distinct {p,q}=2,  blocks 1
48	//	[20,30): occ 0, distinct 0, blocks 0
49	//	totals: occ 7, window-distinct {a,b,p,q,r}=5, blocks 4, missing 0
50	//
51	// The two complete answers differ in every discriminating field, so any
52	// stitched-together answer stands out.
53	
54	var reorgStatsQuery = TimeStatsQuery{From: 1, Start: 0, End: 30, StepSeconds: 10}
55	
56	func reorgOldChainBlocks() []Block {
57		return []Block{
58			timeBlock(1, "h1", "g", []string{"a", "a"}, intptr(0)),
59			timeBlock(2, "h2", "h1", []string{"b"}, intptr(5)),
60			timeBlock(3, "h3", "h2", []string{"a", "c"}, intptr(15)),
61			timeBlock(4, "h4", "h3", []string{"d", "d", "e"}, nil),
62			timeBlock(5, "h5", "h4", []string{"f"}, intptr(25)),
63		}
64	}
65	
66	func reorgNewBranch() []Block {
67		return []Block{
68			timeBlock(3, "j3", "h2", []string{"p", "p", "q"}, intptr(10)),
69			timeBlock(4, "j4", "j3", []string{"r"}, intptr(0)),
70		}
71	}
72	
73	func buildOldChain(t *testing.T) *Index {
74		t.Helper()
75		index := New()
76		for _, b := range reorgOldChainBlocks() {
77			if err := index.Append(b); err != nil {
78				t.Fatalf("setup append at %d: %v", b.Height, err)
79			}
80		}
81		return index
82	}
83	
84	// literalOldStats is the hand-derived complete old-chain answer.
85	func literalOldStats() TimeStats {
86		return TimeStats{
87			Buckets: []TimeBucket{
88				{Start: 0, End: 10, TxCount: 3, DistinctTxIDs: 2, Blocks: 2},
89				{Start: 10, End: 20, TxCount: 2, DistinctTxIDs: 2, Blocks: 1},
90				{Start: 20, End: 30, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
91			},
92			Totals:            TimeTotals{TxCount: 6, DistinctTxIDs: 4, Blocks: 4},
93			FromHeight:        1,
94			ToHeight:          5,
95			MissingTimeBlocks: 1,
96		}
97	}
98	
99	// literalNewStats is the hand-derived complete new-chain answer.
100	func literalNewStats() TimeStats {
101		return TimeStats{
102			Buckets: []TimeBucket{
103				{Start: 0, End: 10, TxCount: 4, DistinctTxIDs: 3, Blocks: 3},
104				{Start: 10, End: 20, TxCount: 3, DistinctTxIDs: 2, Blocks: 1},
105				{Start: 20, End: 30, TxCount: 0, DistinctTxIDs: 0, Blocks: 0},
106			},
107			Totals:            TimeTotals{TxCount: 7, DistinctTxIDs: 5, Blocks: 4},
108			FromHeight:        1,
109			ToHeight:          4,
110			MissingTimeBlocks: 0,
111		}
112	}
113	
114	// referenceTimeStats is an independent oracle: it derives the full TimeStats
115	// from an explicitly supplied, complete ordered chain rather than from the
116	// index under test, so a shared bug in QueryTimeStats cannot make an
117	// expectation match itself.
118	func referenceTimeStats(chain []Block, q TimeStatsQuery) TimeStats {
119		tip := int64(len(chain))
120		from := q.From
121		if from == 0 {
122			from = 1
123		}
124		to := q.To
125		if to == 0 || to > tip {
126			to = tip
127		}
128		width := q.End - q.Start
129		count := width / q.StepSeconds
130		if width%q.StepSeconds != 0 {
131			count++
132		}
133		stats := TimeStats{
134			Buckets:    make([]TimeBucket, count),
135			FromHeight: from,
136			ToHeight:   to,
137		}
138		for i := range stats.Buckets {
139			stats.Buckets[i].Start = q.Start + q.StepSeconds*int64(i)
140			end := q.Start + q.StepSeconds*(int64(i)+1)
141			if end > q.End {
142				end = q.End
143			}
144			stats.Buckets[i].End = end
145		}
146		if from > to {
147			return stats
148		}
149		var filter map[string]struct{}
150		if len(q.TxIDs) > 0 {
151			filter = map[string]struct{}{}
152			for _, id := range q.TxIDs {
153				filter[id] = struct{}{}
154			}
155		}
156		type acc struct {
157			occ    int64
158			ids    map[string]struct{}
159			blocks int64
160		}
161		per := make([]acc, count)
162		windowIDs := map[string]struct{}{}
163		for height := from; height <= to; height++ {
164			block := chain[height-1]
165			if block.Time == nil {
166				stats.MissingTimeBlocks++
167				continue
168			}
169			t := *block.Time
170			if t < q.Start || t >= q.End {
171				continue
172			}
173			bucket := (t - q.Start) / q.StepSeconds
174			matched := false
175			for _, tx := range block.Txs {
176				if filter != nil {
177					if _, ok := filter[tx]; !ok {
178						continue
179					}
180				}
181				stats.Totals.TxCount++
182				per[bucket].occ++
183				if per[bucket].ids == nil {
184					per[bucket].ids = map[string]struct{}{}
185				}
186				per[bucket].ids[tx] = struct{}{}
187				windowIDs[tx] = struct{}{}
188				matched = true
189			}
190			if matched {
191				per[bucket].blocks++
192				stats.Totals.Blocks++
193			}
194		}
195		for i := range per {
196			stats.Buckets[i].TxCount = per[i].occ
197			stats.Buckets[i].DistinctTxIDs = int64(len(per[i].ids))
198			stats.Buckets[i].Blocks = per[i].blocks
199		}
200		stats.Totals.DistinctTxIDs = int64(len(windowIDs))
201		return stats
202	}
203	
204	// classifyTimeStats accepts got only when it is byte-for-byte the complete
205	// answer of exactly one chain. Anything else — fields stitched from old and
206	// new, or plain corruption — is rejected with a report naming the offending
207	// piece. It deliberately does NOT treat "per-bucket occurrence counts sum to
208	// the total" as sufficient: that equality holds for several mixed answers.
209	func classifyTimeStats(got, oldRef, newRef TimeStats) error {
210		if reflect.DeepEqual(got, oldRef) {
211			return nil
212		}
213		if reflect.DeepEqual(got, newRef) {
214			return nil
215		}
216		var report strings.Builder
217		fmt.Fprintln(&report, "QueryTimeStats return does not match one complete main chain:")
218		if len(got.Buckets) != len(oldRef.Buckets) || len(got.Buckets) != len(newRef.Buckets) {
219			fmt.Fprintf(&report, "  Buckets length        got=%d old=%d new=%d -> neither\n",
220				len(got.Buckets), len(oldRef.Buckets), len(newRef.Buckets))
221			return fmt.Errorf("%s  => CORRUPT: segment count matches neither chain", report.String())
222		}
223		tags := map[string]bool{}
224		tag := func(name string, gotV, oldV, newV any) string {
225			matchesOld := reflect.DeepEqual(gotV, oldV)
226			matchesNew := reflect.DeepEqual(gotV, newV)
227			label := "neither"
228			switch {
229			case matchesOld && matchesNew:
230				label = "both"
231			case matchesOld:
232				label = "OLD"
233				tags["old"] = true
234			case matchesNew:
235				label = "NEW"
236				tags["new"] = true
237			}
238			fmt.Fprintf(&report, "  %-22s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
239			return label
240		}
241		tag("FromHeight", got.FromHeight, oldRef.FromHeight, newRef.FromHeight)
242		tag("ToHeight", got.ToHeight, oldRef.ToHeight, newRef.ToHeight)
243		tag("MissingTimeBlocks", got.MissingTimeBlocks, oldRef.MissingTimeBlocks, newRef.MissingTimeBlocks)
244		tag("Totals", got.Totals, oldRef.Totals, newRef.Totals)
245		for i := range got.Buckets {
246			tag(fmt.Sprintf("Buckets[%d]", i), got.Buckets[i], oldRef.Buckets[i], newRef.Buckets[i])
247		}
248		switch {
249		case tags["old"] && tags["new"]:
250			fmt.Fprintf(&report, "  => MIXED: pieces come from both the old and the new chain; one return must reflect a single main chain")
251		default:
252			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new chain")
253		}
254		return fmt.Errorf("%s", report.String())
255	}
256	
257	// bucketOccurrenceSumEqualsTotal is the deliberately weak check that this
258	// regression must be stronger than: it holds for several old/new mixtures.
259	func bucketOccurrenceSumEqualsTotal(s TimeStats) bool {
260		var sum int64
261		for _, b := range s.Buckets {
262			sum += b.TxCount
263		}
264		return sum == s.Totals.TxCount
265	}
266	
267	func TestReorgTimeStatsReferenceMatchesHandDerived(t *testing.T) {
268		oldChain := reorgOldChainBlocks()
269		if got, want := referenceTimeStats(oldChain, reorgStatsQuery), literalOldStats(); !reflect.DeepEqual(got, want) {
270			t.Fatalf("old-chain oracle=%+v\nwant=%+v", got, want)
271		}
272		// The oracle derives the new chain from the retained ancestor plus the
273		// replacement branch, exactly what the index must hold after the reorg.
274		newChain := append(append([]Block{}, oldChain[:2]...), reorgNewBranch()...)
275		if got, want := referenceTimeStats(newChain, reorgStatsQuery), literalNewStats(); !reflect.DeepEqual(got, want) {
276			t.Fatalf("new-chain oracle=%+v\nwant=%+v", got, want)
277		}
278	}
279	
280	// The counting semantics the regression rests on, asserted directly for each
281	// chain so the guarantees do not hide inside a DeepEqual.
282	func TestReorgTimeStatsCountingSemanticsOnBothChains(t *testing.T) {
283		old := literalOldStats()
284		if old.Buckets[0].TxCount != 3 || old.Buckets[0].DistinctTxIDs != 2 {
285			t.Fatalf("old [0,10): duplicate a must count twice but as one id: %+v", old.Buckets[0])
286		}
287		if old.Buckets[1].DistinctTxIDs != 2 {
288			t.Fatalf("old [10,20) distinct: %+v", old.Buckets[1])
289		}
290		if old.Totals.DistinctTxIDs != 5-1 { // a in two segments must count once over the window
291			t.Fatalf("old window distinct must dedup a across segments: %+v", old.Totals)
292		}
293		if old.MissingTimeBlocks != 1 {
294			t.Fatalf("missing-time h4 must count once toward missing: %d", old.MissingTimeBlocks)
295		}
296		if old.Totals.Blocks != 4 {
297			t.Fatalf("h4 has three matching txs but no time; it must add no block, want 4: %d", old.Totals.Blocks)
298		}
299	
300		new := literalNewStats()
301		if new.MissingTimeBlocks != 0 {
302			t.Fatalf("zero-time j4 is a real time, not missing: %d", new.MissingTimeBlocks)
303		}
304		if new.Buckets[0].TxCount != 4 || new.Buckets[0].Blocks != 3 {
305			t.Fatalf("zero-time j4 must enter [0,10): %+v", new.Buckets[0])
306		}
307		if len(new.Buckets) != 3 || new.Buckets[2] != (TimeBucket{Start: 20, End: 30}) {
308			t.Fatalf("empty [20,30) segment must still be returned zeroed: %+v", new.Buckets)
309		}
310		if new.Buckets[1].TxCount != 3 || new.Buckets[1].DistinctTxIDs != 2 {
311			t.Fatalf("new [10,20): p twice counts twice but as one id: %+v", new.Buckets[1])
312		}
313		if new.ToHeight != 4 || new.Totals.TxCount != 7 {
314			t.Fatalf("shortened chain must pin tip 4 and drop f: %+v", new)
315		}
316	}
317	
318	func TestQueryTimeStatsBeforeAndAfterShorteningReorg(t *testing.T) {
319		index := buildOldChain(t)
320		oldRef := literalOldStats()
321	
322		before, err := index.QueryTimeStats(reorgStatsQuery)
323		if err != nil {
324			t.Fatal(err)
325		}
326		if err := classifyTimeStats(before, oldRef, literalNewStats()); err != nil {
327			t.Fatal(err)
328		}
329	
330		dropped, err := index.Reorg(reorgNewBranch())
331		if err != nil {
332			t.Fatalf("shortening reorg refused: %v", err)
333		}
334		if want := []int64{3, 4, 5}; !reflect.DeepEqual(dropped, want) {
335			t.Fatalf("dropped=%v, want %v", dropped, want)
336		}
337		if index.Tip != 4 {
338			t.Fatalf("tip=%d, want shortened tip 4", index.Tip)
339		}
340	
341		// After the reorg returns, only the complete new-chain answer is allowed.
342		after, err := index.QueryTimeStats(reorgStatsQuery)
343		if err != nil {
344			t.Fatal(err)
345		}
346		if !reflect.DeepEqual(after, literalNewStats()) {
347			t.Fatalf("post-reorg query not wholly on the new chain:\n%+v", after)
348		}
349		if after.ToHeight != 4 {
350			t.Fatalf("upper height must follow the shortened tip, got %d", after.ToHeight)
351		}
352		if after.Buckets[2].TxCount != 0 || after.MissingTimeBlocks != 0 {
353			t.Fatalf("removed height 5 tx f or old missing count leaked: %+v", after)
354		}
355		// The removed height really is gone from the chain.
356		if _, ok := index.Blocks[5]; ok {
357			t.Fatal("height 5 still present after shortening reorg")
358		}
359		if _, ok := index.ByHash["h5"]; ok {
360			t.Fatal("removed hash h5 still indexed")
361		}
362	}
363	
364	// Installs one-shot rendezvous hooks and guarantees they are removed.
365	type reorgStatsHooks struct {
366		queryParked   chan struct{}
367		releaseQuery  chan struct{}
368		reorgParked   chan struct{}
369		releaseReorg  chan struct{}
370		queryHookOnce sync.Once
371		reorgHookOnce sync.Once
372	}
373	
374	func installReorgStatsHooks(t *testing.T) *reorgStatsHooks {
375		t.Helper()
376		h := &reorgStatsHooks{
377			queryParked:  make(chan struct{}),
378			releaseQuery: make(chan struct{}),
379			reorgParked:  make(chan struct{}),
380			releaseReorg: make(chan struct{}),
381		}
382		statsQueryHookLocked = func(to int64) {
383			h.queryHookOnce.Do(func() { close(h.queryParked) })
384			<-h.releaseQuery
385		}
386		reorgAppliedHookLocked = func(newTip int64) {
387			if newTip != 4 {
388				t.Errorf("reorg hook saw newTip=%d, want 4", newTip)
389			}
390			h.reorgHookOnce.Do(func() { close(h.reorgParked) })
391			<-h.releaseReorg
392		}
393		t.Cleanup(func() {
394			statsQueryHookLocked = nil
395			reorgAppliedHookLocked = nil
396		})
397		return h
398	}
399	
400	// A query that has pinned the OLD tip (5) and is still holding the lock when
401	// the reorg starts must finish on the complete old chain.
402	func TestQueryTimeStatsInFlightObservesCompleteOldChain(t *testing.T) {
403		index := buildOldChain(t)
404		h := installReorgStatsHooks(t)
405		oldRef, newRef := literalOldStats(), literalNewStats()
406	
407		result := make(chan TimeStats, 1)
408		errCh := make(chan error, 1)
409		go func() {
410			stats, err := index.QueryTimeStats(reorgStatsQuery)
411			if err != nil {
412				errCh <- err
413				return
414			}
415			result <- stats
416		}()
417	
418		<-h.queryParked // query holds index.mu and has pinned tip 5
419		reorgDone := make(chan struct{})
420		go func() {
421			if _, err := index.Reorg(reorgNewBranch()); err != nil {
422				errCh <- err
423			}
424			close(reorgDone)
425		}()
426	
427		// Let the parked query scan and finish first; the reorg cannot touch the
428		// chain until the query drops the lock.
429		close(h.releaseQuery)
430		var got TimeStats
431		select {
432		case got = <-result:
433		case err := <-errCh:
434			t.Fatalf("concurrent call failed: %v", err)
435		}
436		if err := classifyTimeStats(got, oldRef, newRef); err != nil {
437			t.Fatalf("in-flight query did not return one complete chain:\n%v", err)
438		}
439		if !reflect.DeepEqual(got, oldRef) {
440			t.Fatalf("query holding the lock across reorg start must see old chain:\n%+v", got)
441		}
442		close(h.releaseReorg) // unblock the parked reorg
443		<-reorgDone
444	}
445	
446	// A query issued while a successful reorg is committed but has not yet
447	// returned (new chain installed under the lock) must wait and then observe
448	// the complete NEW chain, including the shortened upper height.
449	func TestQueryTimeStatsInFlightObservesCompleteNewChain(t *testing.T) {
450		index := buildOldChain(t)
451		h := installReorgStatsHooks(t)
452		oldRef, newRef := literalOldStats(), literalNewStats()
453	
454		reorgErr := make(chan error, 1)
455		go func() {
456			_, err := index.Reorg(reorgNewBranch())
457			reorgErr <- err
458		}()
459		<-h.reorgParked // new branch applied (tip 4), Reorg still holds the lock
460	
461		result := make(chan TimeStats, 1)
462		go func() {
463			stats, err := index.QueryTimeStats(reorgStatsQuery)
464			if err != nil {
465				t.Errorf("query during reorg failed: %v", err)
466				return
467			}
468			result <- stats
469		}()
470	
471		// Releasing the reorg lets it return and hands the lock to the waiting
472		// query; the chain the query can first see is already entirely the new one.
473		close(h.releaseReorg)
474		if err := <-reorgErr; err != nil {
475			t.Fatalf("reorg failed: %v", err)
476		}
477		close(h.releaseQuery) // no query parks in this timing, but keep the seam drained
478	
479		got := <-result
480		if err := classifyTimeStats(got, oldRef, newRef); err != nil {
481			t.Fatalf("query across reorg commit did not return one complete chain:\n%v", err)
482		}
483		if !reflect.DeepEqual(got, newRef) {
484			t.Fatalf("query after reorg commit must see the complete new chain:\n%+v", got)
485		}
486	}
487	
488	// The validator must actually catch old/new mixtures — including ones where
489	// the per-bucket occurrence counts still sum to the window total.
490	func TestClassifyTimeStatsRejectsMixedAndCorruptReturns(t *testing.T) {
491		oldRef, newRef := literalOldStats(), literalNewStats()
492		if err := classifyTimeStats(oldRef, oldRef, newRef); err != nil {
493			t.Fatalf("pure old answer rejected: %v", err)
494		}
495		if err := classifyTimeStats(newRef, oldRef, newRef); err != nil {
496			t.Fatalf("pure new answer rejected: %v", err)
497		}
498	
499		// Mixture 1: new-chain buckets and totals but the stale OLD upper height
500		// and missing-time count. Bucket occurrences sum to the total, so the
501		// naive sum check accepts it; the complete-chain check must not.
502		mixed1 := newRef
503		mixed1.ToHeight = oldRef.ToHeight
504		mixed1.MissingTimeBlocks = oldRef.MissingTimeBlocks
505		if !bucketOccurrenceSumEqualsTotal(mixed1) {
506			t.Fatal("test setup: mixed1 is meant to pass the weak sum check")
507		}
508		if err := classifyTimeStats(mixed1, oldRef, newRef); err == nil {
509			t.Fatal("new-chain counts under the old tip height were accepted")
510		} else if !strings.Contains(err.Error(), "MIXED") {
511			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
512		}
513	
514		// Mixture 2: old-chain buckets and totals but the NEW shortened upper
515		// height — claims tip 4 while still counting removed height 5's f.
516		mixed2 := oldRef
517		mixed2.ToHeight = newRef.ToHeight
518		if !bucketOccurrenceSumEqualsTotal(mixed2) {
519			t.Fatal("test setup: mixed2 is meant to pass the weak sum check")
520		}
521		if err := classifyTimeStats(mixed2, oldRef, newRef); err == nil {
522			t.Fatal("old-chain counts under the new tip height were accepted")
523		} else if !strings.Contains(err.Error(), "MIXED") {
524			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
525		}
526	
527		// Mixture 3: new range and missing count but old per-bucket shape and a
528		// stitched total — cross-component mix with no consistent sum.
529		mixed3 := newRef
530		mixed3.Buckets = oldRef.Buckets
531		mixed3.Totals.TxCount = oldRef.Totals.TxCount
532		if err := classifyTimeStats(mixed3, oldRef, newRef); err == nil {
533			t.Fatal("old buckets against the new range were accepted")
534		} else if !strings.Contains(err.Error(), "MIXED") {
535			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
536		}
537	
538		// Corruption that belongs to neither chain must also be rejected.
539		corrupt := newRef
540		corrupt.Buckets[0].TxCount++
541		corrupt.Totals.TxCount++
542		if err := classifyTimeStats(corrupt, oldRef, newRef); err == nil {
543			t.Fatal("corrupt answer matching neither chain was accepted")
544		}
545	}
546	
547	// Sustained overlap: reorgs alternate between the old and the shortened new
548	// branch while readers query continuously. Every answer must classify as one
549	// complete chain; success never depends on which side of the reorg a query
550	// happened to land. Deterministic, offline, and timing-independent — a torn
551	// answer fails regardless of scheduling.
552	func TestQueryTimeStatsRepeatedShorteningReorgsStayConsistent(t *testing.T) {
553		index := buildOldChain(t)
554		oldRef, newRef := literalOldStats(), literalNewStats()
555		oldBranch := reorgOldChainBlocks()[2:] // h3,h4,h5 rooted at h2, restores tip 5
556	
557		const reorgers = 2
558		const rounds = 40
559		const readers = 4
560		const reads = 80
561	
562		stop := make(chan struct{})
563		var wg sync.WaitGroup
564		for r := 0; r < reorgers; r++ {
565			wg.Add(1)
566			go func(seed int) {
567				defer wg.Done()
568				for i := 0; i < rounds; i++ {
569					select {
570					case <-stop:
571						return
572					default:
573					}
574					branch := reorgNewBranch()
575					if (i+seed)%2 == 0 {
576						branch = oldBranch
577					}
578					if _, err := index.Reorg(branch); err != nil {
579						t.Errorf("reorg failed: %v", err)
580						return
581					}
582				}
583			}(r)
584		}
585		for r := 0; r < readers; r++ {
586			wg.Add(1)
587			go func() {
588				defer wg.Done()
589				for i := 0; i < reads; i++ {
590					select {
591					case <-stop:
592						return
593					default:
594					}
595					stats, err := index.QueryTimeStats(reorgStatsQuery)
596					if err != nil {
597						t.Errorf("query failed: %v", err)
598						return
599					}
600					if err := classifyTimeStats(stats, oldRef, newRef); err != nil {
601						t.Errorf("%v", err)
602						return
603					}
604				}
605			}()
606		}
607		wg.Wait()
608		close(stop)
609	
610		// Leave the index deterministically on the new chain and re-verify.
611		if _, err := index.Reorg(reorgNewBranch()); err != nil {
612			t.Fatalf("final reorg failed: %v", err)
613		}
614		final, err := index.QueryTimeStats(reorgStatsQuery)
615		if err != nil {
616			t.Fatal(err)
617		}
618		if !reflect.DeepEqual(final, newRef) {
619			t.Fatalf("final state is not the complete new chain:\n%+v", final)
620		}
621	}
